-- Schema from eb7120c before the Horde terminology rename.
CREATE TABLE IF NOT EXISTS outcomes(id TEXT PRIMARY KEY, objective TEXT NOT NULL, repo TEXT NOT NULL, status TEXT NOT NULL, settings TEXT NOT NULL, plan TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(outcome TEXT NOT NULL REFERENCES outcomes(id), revision INTEGER NOT NULL, plan TEXT NOT NULL, created INTEGER NOT NULL, PRIMARY KEY(outcome,revision));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, outcome TEXT NOT NULL REFERENCES outcomes(id), name TEXT NOT NULL, spec TEXT NOT NULL, state TEXT NOT NULL, result TEXT, UNIQUE(outcome,name));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY, task TEXT NOT NULL REFERENCES tasks(id), worker TEXT, state TEXT NOT NULL, started INTEGER NOT NULL, finished INTEGER, pid INTEGER, result TEXT, usage TEXT);
CREATE TABLE IF NOT EXISTS workers(id TEXT PRIMARY KEY, outcome TEXT NOT NULL REFERENCES outcomes(id), task TEXT REFERENCES tasks(id), status TEXT NOT NULL, token_hash TEXT NOT NULL, workspace TEXT, branch TEXT, base TEXT, updated INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS workspace_owner ON workers(workspace) WHERE workspace IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS branch_owner ON workers(outcome,branch) WHERE branch IS NOT NULL;
CREATE TABLE IF NOT EXISTS channels(outcome TEXT NOT NULL REFERENCES outcomes(id), name TEXT NOT NULL, worker TEXT NOT NULL REFERENCES workers(id), PRIMARY KEY(outcome,name,worker));
CREATE TABLE IF NOT EXISTS messages(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT UNIQUE NOT NULL, outcome TEXT NOT NULL REFERENCES outcomes(id), sender TEXT NOT NULL REFERENCES workers(id), destination TEXT NOT NULL, body TEXT NOT NULL, refs TEXT NOT NULL, actionable INTEGER NOT NULL, created INTEGER NOT NULL, UNIQUE(sender,id));
CREATE TABLE IF NOT EXISTS receipts(message TEXT NOT NULL REFERENCES messages(id), worker TEXT NOT NULL REFERENCES workers(id), ack INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(message,worker));
CREATE TABLE IF NOT EXISTS cursors(worker TEXT PRIMARY KEY REFERENCES workers(id), seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notifications(worker TEXT PRIMARY KEY REFERENCES workers(id), dispatched_seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS claims(outcome TEXT NOT NULL REFERENCES outcomes(id), path TEXT NOT NULL, worker TEXT NOT NULL REFERENCES workers(id), PRIMARY KEY(outcome,path));
CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, outcome TEXT REFERENCES outcomes(id), kind TEXT NOT NULL, data TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifacts(hash TEXT PRIMARY KEY, size INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_links(outcome TEXT NOT NULL REFERENCES outcomes(id), task TEXT REFERENCES tasks(id), name TEXT NOT NULL, hash TEXT NOT NULL REFERENCES artifacts(hash), inputs TEXT NOT NULL, verified INTEGER NOT NULL, UNIQUE(outcome,task,name,hash));
CREATE TABLE IF NOT EXISTS knowledge(id TEXT PRIMARY KEY, outcome TEXT NOT NULL REFERENCES outcomes(id), task TEXT REFERENCES tasks(id), kind TEXT NOT NULL, content TEXT NOT NULL, provenance TEXT NOT NULL, verified INTEGER NOT NULL, inputs TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_edges(source TEXT NOT NULL REFERENCES knowledge(id), target TEXT NOT NULL REFERENCES knowledge(id), relation TEXT NOT NULL, PRIMARY KEY(source,target,relation));
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY, outcome TEXT NOT NULL REFERENCES outcomes(id), question TEXT NOT NULL, answer TEXT);
CREATE TABLE IF NOT EXISTS question_context(question TEXT PRIMARY KEY REFERENCES questions(id), purpose TEXT NOT NULL, worker TEXT REFERENCES workers(id));
CREATE TABLE IF NOT EXISTS integrations(id TEXT PRIMARY KEY, outcome TEXT NOT NULL REFERENCES outcomes(id), worker TEXT NOT NULL REFERENCES workers(id), commit_id TEXT NOT NULL, state TEXT NOT NULL, evidence TEXT, created INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS integration_once ON integrations(outcome,worker,commit_id);
CREATE TABLE IF NOT EXISTS workflow_outputs(outcome TEXT PRIMARY KEY REFERENCES outcomes(id), outputs TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS external_ops(outcome TEXT NOT NULL REFERENCES outcomes(id), name TEXT NOT NULL, state TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(outcome,name));
INSERT OR IGNORE INTO notifications(worker) SELECT id FROM workers;
CREATE TABLE IF NOT EXISTS outcome_tree(outcome TEXT PRIMARY KEY REFERENCES outcomes(id),root TEXT NOT NULL,parent TEXT,caller_worker TEXT,depth INTEGER NOT NULL,request_id TEXT,request_hash TEXT,version INTEGER NOT NULL DEFAULT 1,limits TEXT NOT NULL,UNIQUE(parent,request_id));
CREATE TABLE IF NOT EXISTS context_records(id TEXT PRIMARY KEY,root TEXT NOT NULL,version INTEGER NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,provenance TEXT NOT NULL,mandatory INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS context_attempts(attempt TEXT PRIMARY KEY,root TEXT NOT NULL,version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS question_routes(question TEXT PRIMARY KEY REFERENCES questions(id),origin TEXT NOT NULL,target TEXT,request_id TEXT NOT NULL,envelope TEXT NOT NULL,answerer TEXT,human_only INTEGER NOT NULL DEFAULT 0,UNIQUE(origin,request_id));
CREATE TABLE IF NOT EXISTS event_receipts(outcome TEXT NOT NULL,consumer TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(outcome,consumer));
CREATE TABLE IF NOT EXISTS outcome_bundles(outcome TEXT NOT NULL,name TEXT NOT NULL,version TEXT NOT NULL,PRIMARY KEY(outcome,name));
CREATE TABLE IF NOT EXISTS remote_environment_leases(outcome TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS app_process_groups(environment TEXT NOT NULL,pid INTEGER NOT NULL,identity TEXT NOT NULL,PRIMARY KEY(environment,pid));
CREATE TABLE IF NOT EXISTS app_process_identity(environment TEXT PRIMARY KEY,identity TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_environments(id TEXT PRIMARY KEY,outcome TEXT NOT NULL,attempt TEXT,kind TEXT NOT NULL,state TEXT NOT NULL,spec TEXT NOT NULL,workspace TEXT NOT NULL,pid INTEGER,created INTEGER NOT NULL,expires INTEGER NOT NULL,evidence TEXT);
CREATE TABLE IF NOT EXISTS foreign_children(parent TEXT NOT NULL,remote_child TEXT NOT NULL,local_child TEXT NOT NULL,PRIMARY KEY(parent,remote_child));
CREATE TABLE IF NOT EXISTS local_child_bases(outcome TEXT PRIMARY KEY,base TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_escalations(question TEXT NOT NULL,caller TEXT NOT NULL,commentary TEXT NOT NULL,PRIMARY KEY(question,caller));
CREATE TABLE IF NOT EXISTS remote_context(outcome TEXT PRIMARY KEY,packet TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS child_acceptance(parent TEXT NOT NULL,child TEXT NOT NULL,version INTEGER NOT NULL,evidence TEXT NOT NULL,PRIMARY KEY(parent,child));
CREATE TABLE IF NOT EXISTS remote_links(outcome TEXT PRIMARY KEY,peer TEXT NOT NULL,remote_id TEXT,state TEXT NOT NULL,request TEXT NOT NULL,base TEXT);
CREATE TABLE IF NOT EXISTS remote_origins(outcome TEXT PRIMARY KEY,owner_peer TEXT NOT NULL,owner_outcome TEXT NOT NULL,UNIQUE(owner_peer,owner_outcome));
CREATE TABLE IF NOT EXISTS runtime_enrollments(runtime TEXT PRIMARY KEY,fingerprint TEXT UNIQUE NOT NULL,token_hash TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runtime_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_capacity(account TEXT NOT NULL,window TEXT NOT NULL,provider TEXT NOT NULL,used REAL,reset INTEGER,observed INTEGER NOT NULL,source TEXT NOT NULL,PRIMARY KEY(account,window));
CREATE TABLE IF NOT EXISTS attempt_accounts(attempt TEXT PRIMARY KEY REFERENCES attempts(id),account TEXT NOT NULL,role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS management_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS management_receipts(consumer TEXT PRIMARY KEY,seq INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS managed_runtimes(id TEXT PRIMARY KEY,profile TEXT NOT NULL,spec TEXT NOT NULL,resource TEXT,state TEXT NOT NULL,version TEXT,created INTEGER NOT NULL,error TEXT);
CREATE TABLE IF NOT EXISTS runtime_operations(id TEXT PRIMARY KEY,runtime TEXT NOT NULL,action TEXT NOT NULL,args TEXT NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL,result TEXT);
PRAGMA user_version=2;
